Test.Description:
create transformer on CK.vUserAuthProvider
as
begin

  inject "/* This header is useless once a real provider has been added.
  " before single part {select UserId = 0};

  inject "*/" after first {union all};

  in single part {select UserId, 'Twitter'}
  begin
     add column UserName = ScreenName, CreationDate, PictureUrl;
  end
  in single part {select UserId, 'Basic'}
  begin   
    add column UserName = N'', CreationDate, PictureUrl='';
  end
  in after single part {select UserId, 'Basic'}
  begin   
     add column UserName, CreationDate, PictureUrl;
  end
end

