create transformer on CK.vDynObjPartTree
as
begin
  replace single {( DynObjId, PartId, Depth, PartPath )} with "( DynObjId, PartId, LayerId, Depth, PartPath )";
  replace all 2 {, p.PartId,} with ", p.PartId, p.LayerId,";
  replace all 2 {CK.tDynObjPart} with "CK.vDynObjPart";
  replace single {, C.PartId, C.Depth,} with ", C.PartId, C.LayerId, C.Depth,";
end

Test.Text:
        -- SetupConfig: {}
        -- 
        create procedure CK.sDynObjAcquirePart
	        @ActorId int,
            @DynObjId int,
	        @PartId int
        as
        begin
	        --[beginsp]

            declare @CurrentParentId int;
            select @CurrentParentId = DynObjId from CK.tDynObjPart where PartId = @PartId;
            if @CurrentParentId is not null
            begin
                exec CK.sDynObjReleasePart @ActorId, @DynObjId, @PartId;
            end

            --<PreAcquirePart revert />

            insert into CK.tDynObjPart( DynObjId, PartId ) values ( @DynObjId, @PartId );

            --<PostAcquirePart /> 

	        --[endsp]
        end

Test.Description:
-- SetupConfig: {}
-- 
create transformer on CK.sDynObjAcquirePart
as
begin
  add parameter @LayerId int = 0;
  in single statement {select @CurrentParentId = DynObjId}
  begin
    replace single {PartId = @PartId} with "PartId = @PartId and LayerId = @LayerId";
  end
  in single statement {exec CK.sDynObjReleasePart}
  begin
    replace single {@PartId} with "@PartId, @LayerId";
  end
  in single statement {insert into}
  begin
    add column LayerId = @LayerId;
  end
end

