      -- SetupConfig: {}
      --
      create procedure CK.sDynObjAcquirePart
        @ActorId int,
        @DynObjId int,
        @PartId int,
        @LayerId int = 0
      as
      begin
          --[beginsp]

          declare @CurrentParentId int;
          select @CurrentParentId = DynObjId from CK.tDynObjPart where PartId = @PartId and LayerId = @LayerId;
          if @CurrentParentId is not null
          begin
            exec CK.sDynObjReleasePart @ActorId, @DynObjId, @PartId, @LayerId;
          end

          --<PreAcquirePart revert />

          insert into CK.tDynObjPart( DynObjId, PartId, LayerId ) values ( @DynObjId, @PartId, @LayerId );

          --<PostAcquirePart /> 

	        --[endsp]
     end

Test.Description:
      -- SetupConfig:{}
      create transformer on CK.vRes
      as
      begin

	      inject "
		      left outer join CK.tResName n on n.ResId = r.ResId" after single {from CK.tRes r};

	      replace single {ResName = 'Auto.' + cast( r.ResId as varchar)} 
	      with   "ResName = IsNull( n.ResName, 'Auto.' + cast( r.ResId as varchar) )";

      end
